    ]
  },
  {
    name: 'HR',
    queries: [
      'HR Manager Austria',
      'People & Culture Manager Wien',
      'Talent Acquisition Manager Österreich'
    ]
  },
  {
    name: 'Engineering',
    queries: [
      'Engineering Manager Austria',
      'Technical Lead Wien',
      'Project Engineer Österreich'
    ]
  },
  {
    name: 'Operations',
    queries: [
      'Operations Manager Austria',
      'Supply Chain Manager Wien',
      'Logistics Manager Österreich'
    ]
  }
];

// Calculate today's category based on day of year
const startDate = new Date('2025-01-01');
const today = new Date();
const daysSinceStart = Math.floor((today - startDate) / (1000 * 60 * 60 * 24));
const categoryIndex = daysSinceStart % categories.length;

const todayCategory = categories[categoryIndex];
const tomorrowCategory = categories[(categoryIndex + 1) % categories.length];

return [{
  json: {
    today_category: todayCategory.name,
    today_queries: todayCategory.queries,
    tomorrow_category: tomorrowCategory.name,
    date: today.toISOString().split('T')[0],
    day_of_week: today.toLocaleDateString('de-DE', { weekday: 'long' })
  }
}];

