// Combine results from all merged job sources
// Data comes from Merge node - each item has source info
const allItems = $input.all();

// Separate Serper results (have 'organic' array) from Apify results
const serperResults = [];
const apifyResults = [];

for (const item of allItems) {
  const data = item.json;
  if (data.organic) {
    // This is a Serper result
    serperResults.push(...data.organic);
  } else if (data.companyName || data.title) {
    // This is an Apify LinkedIn job result
    apifyResults.push(data);
  } else if (Array.isArray(data)) {
    // Apify results might come as array
    apifyResults.push(...data);
  }
}

// Blacklist of companies and job portals to exclude
const blacklist = [
  'PSA', 'Drees & Sommer', 'LKW Walter', 'Cyan Security', 'Schmachtl',
  'Netconomy', 'Lisec', 'Binderholz', 'Post', 'Still', 'KUKA', 'Kotanyi',
  'Rail Power Systems', 'Doka', 'Hobex', 'Mubea', 'XXXL', 'Ortner', 'Axians',
  'ARAG', 'Planradar', 'Haberkorn', 'Tractive', 'Bühler', 'Salesianer',
  'Lasselsberger', 'Ebcont', 'Waterdrop', 'Hoerbiger', 'Verbund', 'Uniqa',
  'RBI', 'Bawag', 'Bitpanda', 'Dynatrace', 'Storyblok', 'IKEA', 'Mjam'
];

const recruitingKeywords = [
  'recruiting', 'staffing', 'personalberatung', 'headhunter',
  'hr consulting', 'personaldienstleister', 'zeitarbeit',
  'personalvermittlung', 'executive search', 'randstad', 'hays',
  'michael page', 'robert half', 'adecco', 'manpower'
];

const jobPortals = [
  'indeed.com', 'stepstone', 'karriere.at', 'monster.', 'glassdoor',
  'linkedin.com/jobs', 'xing.com/jobs', 'jobs.at', 'willhaben.at/jobs'
];

function isBlacklisted(company) {
  if (!company) return true;
  const lower = company.toLowerCase();
  return blacklist.some(bl => lower.includes(bl.toLowerCase()));
}

function isRecruitingAgency(text) {
  if (!text) return false;
  const lower = text.toLowerCase();
  return recruitingKeywords.some(kw => lower.includes(kw));
}

function isJobPortal(url) {
  if (!url) return false;
  const lower = url.toLowerCase();
  return jobPortals.some(portal => lower.includes(portal));
}

function extractCompanyFromUrl(url) {
  if (!url) return null;

  // Personio pattern: company.jobs.personio.com
  const personioMatch = url.match(/([a-z0-9-]+)\.jobs\.personio\.(?:com|de)/i);
  if (personioMatch) {
    return personioMatch[1].replace(/-/g, ' ').replace(/\b\w/g, l => l.toUpperCase());
  }

  // karriere.at pattern: firma/companyname
  const karriereMatch = url.match(/karriere\.at\/(?:firma|f)\/([a-z0-9-]+)/i);
  if (karriereMatch) {
    return karriereMatch[1].replace(/-/g, ' ').replace(/\b\w/g, l => l.toUpperCase());
  }

  return null;
}

function cleanCompanyName(name) {
  if (!name) return '';
  return name
    .replace(/\s*(GmbH|AG|SE|KG|OG|e\.U\.|& Co\.?|Corp\.?|Inc\.?|Ltd\.?)\s*/gi, '')
    .trim()
    .replace(/[.,\-]+$/, '');
}

function guessDomain(company) {
  if (!company) return '';
  const clean = company.toLowerCase()
    .replace(/\s*(gmbh|ag|se|kg|& co\.?|inc\.?|ltd\.?)\s*/gi, '')
    .replace(/[^a-z0-9]/g, '');
  return clean ? `${clean}.at` : '';
}

function parseSalary(text) {
  if (!text) return null;
  const clean = text.toLowerCase().replace(/[.,]/g, '');

  // Look for numbers like 65000, 65.000, 65k
  const match = clean.match(/(\d{2,3})[\s]?(\d{3})/);
  if (match) return parseInt(match[1]) * 1000 + parseInt(match[2]);

  const kMatch = clean.match(/(\d{2,3})k/);
  if (kMatch) return parseInt(kMatch[1]) * 1000;

  return null;
}

const jobs = [];
const seenCompanies = new Set();

// Process Serper results
for (const result of serperResults) {
  const url = result.link || '';
  const title = result.title || '';
  const snippet = result.snippet || '';

  // Skip job portals
  if (isJobPortal(url)) continue;

  // Extract company
  let company = extractCompanyFromUrl(url);
  if (!company && result.source) company = result.source;
  if (!company) continue;

  // Skip duplicates, blacklisted, recruiting agencies
  const companyKey = company.toLowerCase();
  if (seenCompanies.has(companyKey)) continue;
  if (isBlacklisted(company)) continue;
  if (isRecruitingAgency(company + ' ' + title)) continue;

  seenCompanies.add(companyKey);

  jobs.push({
    job_title: title.split(' - ')[0].split(' | ')[0].trim(),
    company_name: company,
    company_name_clean: cleanCompanyName(company),
    company_domain: guessDomain(company),
    location: 'Austria',
    job_url: url,
    salary_text: snippet.match(/€[\d.,]+/)?.[0] || '',
    salary_num: parseSalary(snippet),
    source: 'Google (Serper)',
    posted_date: new Date().toISOString().split('T')[0]
  });
}

// Process Apify results
if (Array.isArray(apifyResults)) {
  for (const job of apifyResults) {
    const company = job.companyName || '';
    if (!company) continue;

    const companyKey = company.toLowerCase();
    if (seenCompanies.has(companyKey)) continue;
    if (isBlacklisted(company)) continue;
    if (isRecruitingAgency(company + ' ' + job.title)) continue;

    seenCompanies.add(companyKey);

    jobs.push({
      job_title: job.title || '',
      company_name: company,
      company_name_clean: cleanCompanyName(company),
      company_domain: guessDomain(company),
      location: job.location || 'Austria',
      job_url: job.jobUrl || '',
      salary_text: job.salary || '',
      salary_num: parseSalary(job.salary),
      source: 'LinkedIn (Apify)',
      company_linkedin: job.companyUrl || '',
      applicants: job.applicantsCount || '',
      posted_date: job.postedDate || new Date().toISOString().split('T')[0]
    });
  }
}

// Filter for salary >= €65,000
const filtered = jobs.filter(job => {
  // If salary is known, must be >= 65000
  if (job.salary_num && job.salary_num < 65000) return false;
  return true;
});

console.log(`Found ${jobs.length} jobs, ${filtered.length} after salary filter`);

// Return each job as separate item
return filtered.map(job => ({ json: job }));

// Prepare approval email summary
const items = $input.all();

if (items.length === 0) {
  return [{ json: { no_jobs: true, message: 'Keine neuen Jobs heute gefunden.' } }];
}

// Build HTML table
let tableRows = '';
for (let i = 0; i < items.length; i++) {
  const job = items[i].json;
  tableRows += `
    <tr>
      <td style="padding:8px;border:1px solid #ddd;">${i + 1}</td>
      <td style="padding:8px;border:1px solid #ddd;">${job.company_name}</td>
      <td style="padding:8px;border:1px solid #ddd;">${job.job_title}</td>
      <td style="padding:8px;border:1px solid #ddd;">${job.salary_text || '-'}</td>
      <td style="padding:8px;border:1px solid #ddd;"><a href="${job.job_url}">Link</a></td>
    </tr>`;
}

const html = `
<html>
<body style="font-family:Arial,sans-serif;">
  <h2>🎯 TalentMonkeys Lead Approval - ${new Date().toLocaleDateString('de-DE')}</h2>
  <p>Hallo Flavio,</p>
  <p>Heute wurden <strong>${items.length} neue Jobs</strong> gefunden:</p>

  <table style="border-collapse:collapse;width:100%;">
    <tr style="background:#002d62;color:white;">
      <th style="padding:10px;">#</th>
      <th style="padding:10px;">Firma</th>
      <th style="padding:10px;">Position</th>
      <th style="padding:10px;">Gehalt</th>
      <th style="padding:10px;">Link</th>
    </tr>
    ${tableRows}
  </table>

  <p style="margin-top:20px;">
    <strong>Bitte antworte auf diese Email mit:</strong>
  </p>
  <ul>
    <li><strong>"JA"</strong> oder <strong>"ALLE"</strong> = Alle Leads freigeben</li>
    <li><strong>"NEIN"</strong> = Alle überspringen</li>
    <li><strong>Nummern</strong> z.B. "1,3,5" = Nur diese freigeben</li>
  </ul>

  <p style="color:#666;font-size:12px;margin-top:30px;">
    Automatisch generiert von TalentMonkeys Lead Generation System
  </p>
</body>
</html>`;

return [{
  json: {
    subject: `🎯 Lead Approval: ${items.length} neue Jobs - ${new Date().toLocaleDateString('de-DE')}`,
    html_body: html,
    jobs_count: items.length,
    jobs: items.map((item, i) => ({ ...item.json, index: i + 1 }))
  }
}];

// Parse approval response
const items = $input.all();
const approvedJobs = [];

for (const item of items) {
  const email = item.json;
  const body = (email.snippet || email.text || '').toLowerCase().trim();

  // Get the thread to find original jobs
  // For now, we'll fetch from Google Sheets

  if (body.includes('ja') || body.includes('alle') || body.includes('yes') || body.includes('all')) {
    // Approve all
    approvedJobs.push({ approval: 'all' });
  } else if (body.includes('nein') || body.includes('no') || body.includes('skip')) {
    // Skip all
    approvedJobs.push({ approval: 'none' });
  } else {
    // Parse numbers like "1,3,5" or "1 3 5"
    const numbers = body.match(/\d+/g);
    if (numbers) {
      approvedJobs.push({ approval: 'selected', indices: numbers.map(n => parseInt(n)) });
    }
  }
}

return approvedJobs.map(a => ({ json: a }));

// Filter jobs based on approval
const approval = $node['Parse Approval Response'].json;
const pendingJobs = $node['Get Pending Jobs'].json;
const allPending = $input.all().map(i => i.json);

if (approval.approval === 'none') {
  // Mark all as skipped
  return [];
}

if (approval.approval === 'all') {
  // Approve all pending jobs
  return allPending.map(job => ({ json: { ...job, approved: true } }));
}

if (approval.approval === 'selected') {
  // Only approve selected indices
  const indices = approval.indices || [];
  return allPending
    .filter((job, i) => indices.includes(i + 1))
    .map(job => ({ json: { ...job, approved: true } }));
}

return [];

// Build enriched lead data
const org = $node['Apollo Enrich Organization'].json.organization || {};
const people = $node['Apollo Search HR Contacts'].json.people || [];
const revealed = $json.matches || [];
const originalJob = $node['Filter Approved Jobs'].json;

const hrContact = revealed[0] || people[0] || {};
const email = hrContact.email || '';
const linkedin = hrContact.linkedin_url || '';

// Skip if no contact info at all
if (!email && !linkedin) {
  return [];
}

return [{
  json: {
    // Company data
    company_name: org.name || originalJob.Company,
    company_domain: org.primary_domain || originalJob.Domain,
    company_website: org.website_url || `https://${originalJob.Domain}`,
    company_employees: org.estimated_num_employees || 0,
    company_industry: org.industry || '',
    company_linkedin: org.linkedin_url || '',

    // Job data
    job_title: originalJob.Job_Title,
    job_url: originalJob.Job_URL,
    job_salary: originalJob.Salary,

    // HR Contact
    hr_first_name: hrContact.first_name || '',
    hr_last_name: hrContact.last_name || '',
    hr_full_name: hrContact.name || `${hrContact.first_name || ''} ${hrContact.last_name || ''}`.trim(),
    hr_title: hrContact.title || '',
    hr_email: email,
    hr_email_verified: hrContact.email_status === 'verified',
    hr_linkedin: linkedin,

    // Metadata
    source: originalJob.Source,
    enriched_at: new Date().toISOString()
  }
}];

// Parse Claude response and extract email
const response = $json;
const leadData = $node['Build Lead Data'].json;

// Native Anthropic node returns text directly or in response.text
let content = response.text || response.message?.content || '';
if (response.content && response.content[0]) {
  content = response.content[0].text || content;
}

// Parse subject and body
let subject = '';
let body = '';

const subjectMatch = content.match(/Betreff:\s*(.+?)\n/);
if (subjectMatch) {
  subject = subjectMatch[1].trim();
  body = content.replace(/Betreff:\s*.+?\n\n?/, '').trim();
} else {
  // Fallback
  subject = `Ihre offene Stelle: ${leadData.job_title}`;
  body = content;
}

// Clean the job title for Instantly
const cleanJobTitle = leadData.job_title
  .split(' - ')[0]
  .split(' | ')[0]
  .split(' bei ')[0]
  .trim();

return [{
  json: {
    ...leadData,
    email_subject: subject,
    email_body: body,
    clean_job_title: cleanJobTitle,
    generated_at: new Date().toISOString()
  }
}];

