// Parse Instantly webhook for reply
const webhook = $json;
const body = webhook.body || webhook;

// Extract reply details
const replyEmail = body.lead_email || body.email || '';
const replyText = body.reply_text || body.message || body.body || '';
const replySubject = body.subject || '';
const campaignId = body.campaign_id || '';

return [{
  json: {
    reply_email: replyEmail,
    reply_text: replyText,
    reply_subject: replySubject,
    campaign_id: campaignId,
    received_at: new Date().toISOString()
  }
}];

// Parse Claude's reply analysis
const response = $json;
const replyData = $node['Parse Instantly Reply'].json;
const leadData = $node['Get Lead Context'].json;

// Native Anthropic node returns text directly or in response.text
let content = response.text || response.message?.content || '';
if (response.content && response.content[0]) {
  content = response.content[0].text || content;
}

// Parse classification
const classMatch = content.match(/KLASSIFIKATION:\s*(POSITIV|NEGATIV|FRAGE|SPÄTER|ABWESEND)/i);
const classification = classMatch ? classMatch[1].toUpperCase() : 'UNKNOWN';

// Parse response
const responseMatch = content.match(/ANTWORT:\s*([\s\S]+?)(?:$|KLASSIFIKATION)/i);
let replyResponse = responseMatch ? responseMatch[1].trim() : '';

// Check if no response needed
const noResponse = replyResponse.toLowerCase().includes('keine') || classification === 'ABWESEND';

return [{
  json: {
    classification: classification,
    reply_response: replyResponse,
    no_response_needed: noResponse,
    lead_email: replyData.reply_email,
    lead_name: leadData.HR_Name || '',
    company: leadData.Company || '',
    original_reply: replyData.reply_text
  }
}];
